import { NotFoundError } from '../../domain/errors/NotFoundError';
import { ProjectRepository } from '../../domain/repositories/ProjectRepository';
import { TaskRepository } from '../../domain/repositories/TaskRepository';
import { parseTaskStatus } from '../../domain/value-objects/TaskStatus';
import { TaskDto, toTaskDto } from '../dto/TaskDto';
import { ListProjectTasksInput } from '../dto/TaskInputs';
import { UseCase } from '../ports/UseCase';
import { Request } from 'express';

export class ListProjectTasksUseCase implements UseCase<ListProjectTasksInput, TaskDto[]> {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  async execute(input: ListProjectTasksInput, request?: Request): Promise<TaskDto[]> {
    const project = await this.projects.findById(input.projectId);
    if (project === undefined) {
      throw new NotFoundError('Project', input.projectId);
    }

    const tasks = await this.tasks.findByProject(project.id, {
      status: input.status === undefined ? undefined : parseTaskStatus(input.status),
      assigneeId: input.assigneeId,
    });
    return tasks.map(toTaskDto);
  }
}

